const settleRoutine = `-- name: SettleRoutine :exec
UPDATE routines SET state = ?1, paused_reason = ?2, next_run_at = ?3, failures = ?4,
    alerted_at = ?5
WHERE id = ?6
`

type SettleRoutineParams struct {
	State        string
	PausedReason string
	NextRunAt    sql.NullInt64
	Failures     int64
	AlertedAt    sql.NullInt64
	ID           string
}

// What a run's end means for its Routine. It is not a change of the Routine: updated_at stays.
func (q *Queries) SettleRoutine(ctx context.Context, arg SettleRoutineParams) error {
	_, err := q.db.ExecContext(ctx, settleRoutine,
		arg.State,
		arg.PausedReason,
		arg.NextRunAt,
		arg.Failures,
		arg.AlertedAt,
		arg.ID,
	)
	return err
}

const skipRoutineTime = `-- name: SkipRoutineTime :exec
UPDATE routines SET next_run_at = ?1, skipped = skipped + 1, last_skipped_at = ?2 WHERE id = ?3
`

type SkipRoutineTimeParams struct {
	NextRunAt sql.NullInt64
	SkippedAt sql.NullInt64
	ID        string
}

// A due time that passed while a run was live.
